'use strict';
/**
 * Bundles every src/**\/*.js (CommonJS) into a single dependency-free engine.js (UMD):
 *   Node:    const E = require('./engine.js')
 *   Browser: window.MathEngine
 * Relative requires ('./core', '../expr', './templates') are resolved inside the bundle.
 * Refuses DOM / network / storage / eval usage anywhere in src/.
 * Usage: node tools/bundle-engine.js
 */
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const srcDir = path.join(root, 'src');
const forbidden = /\b(document|window\.|localStorage|sessionStorage|fetch\(|XMLHttpRequest|eval\(|new Function|Math\.random)\b/;

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))
    .flatMap(e => e.isDirectory() ? walk(path.join(dir, e.name)) : (e.name.endsWith('.js') ? [path.join(dir, e.name)] : []));
}
let modules = '';
const files = walk(srcDir);
for (const file of files) {
  const rel = './' + path.relative(srcDir, file).split(path.sep).join('/').replace(/\.js$/, '');
  const src = fs.readFileSync(file, 'utf8');
  if (forbidden.test(src.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, ''))) throw new Error(`${rel} uses a forbidden API`);
  modules += `  defs[${JSON.stringify(rel)}] = function (module, exports, require) {\n${src}\n  };\n`;
}
const out = `/* engine.js — generated by tools/bundle-engine.js. Do not edit; edit src/ instead. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.MathEngine = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';
  var defs = {}, cache = {};
${modules}
  function resolve(from, p) {
    var parts = from.split('/').slice(0, -1);
    p.split('/').forEach(function (seg) {
      if (seg === '..') parts.pop(); else if (seg !== '.' && seg !== '') parts.push(seg);
    });
    var name = parts.join('/');
    if (name.indexOf('./') !== 0) name = './' + name;
    if (!defs[name] && defs[name + '/index']) name = name + '/index';
    return name;
  }
  function req(name) {
    if (cache[name]) return cache[name].exports;
    if (!defs[name]) throw new Error('engine bundle: missing module ' + name);
    var m = { exports: {} };
    cache[name] = m;
    defs[name](m, m.exports, function (p) { return req(resolve(name, p)); });
    return m.exports;
  }
  return req('./index');
});
`;
fs.writeFileSync(path.join(root, 'engine.js'), out);
console.log(`engine.js written (${out.length} bytes, ${files.length} modules)`);
